0, rewinds: 0, completed: false,\n    safety: { isolated: false, lockPresent: false, locked: false, tagged: false, residualCleared: false, verified: false },\n  };\n}\n\nexport function inspect(run, targetId) {\n  if (!targetIds.has(targetId)) throw new RangeError('알 수 없는 조사 대상입니다.');\n  run.observed.add(targetId);\n  return TARGETS.find(({ id }) => id === targetId);\n}\n\nexport function applyAction(run, actionId) {\n  if (!actionIds.has(actionId)) throw new RangeError('알 수 없는 행동입니다.');\n  if (run.completed) return result('blocked', '이번 작업은 완료했습니다. 다시 연습하면 새 작업을 시작합니다.');\n  if (actionId === 'enter-work') return judgeEntry(run);\n  const safety = run.safety;\n  switch (actionId) {\n    case 'isolate-energy':\n      safety.isolated = true;\n      return result('progress', '실습의 에너지 차단 상태를 완료했습니다. 본인 자물쇠와 표지를 체결하세요.');\n    case 'attach-personal-lock':\n      if (!safety.isolated) return result('blocked', '먼저 에너지를 차단한 뒤 본인 자물쇠를 체결하세요.');\n      safety.lockPresent = true;\n      safety.locked = true;\n      return result('progress', '본인 자물쇠로 차단 상태를 유지했습니다. 표지와 나머지 안전조치를 확인하세요.');\n    case 'attach-wrong-lock':\n      if (!safety.isolated) return result('blocked', '먼저 에너지를 차단해야 잠금 위치를 실습할 수 있습니다.');\n      safety.lockPresent = true;\n      safety.locked = false;\n      safety.tagged = false;\n      safety.residualCleared = false;\n      safety.verified = false;\n      return result('progress', '자물쇠가 보이는 것만으로 안전해지지 않습니다. 해당 설비의 에너지를 차단하고 그 차단 상태를 유지하도록 잠가야 합니다.');\n    case 'attach-tag':\n      if (!safety.locked) return result('blocked', '본인 자물쇠로 차단 장치를 제대로 잠근 뒤 표지를 부착하세요.');\n      safety.tagged = true;\n      return result('progress', '표지를 부착했습니다. 잔류 에너지 안전조치와 차단 확인도 필요합니다.');\n    case 'clear-residual-energy':\n      if (!safety.isolated || !safety.locked) return result('blocked', '에너지 차단과 올바른 본인 잠금부터 완료하세요.');\n      safety.residualCleared = true;\n      return result('progress', '실습의 잔류 에너지 안전조치 상태를 완료했습니다. 차단 확인을 수행하세요.');\n    case 'verify-isolation':\n      if (!safety.isolated || !safety.locked || !safety.residualCleared) {\n        return result('blocked', '차단이 확인되지 않았습니다. 현장 절차에 따라 원인을 확인하고 안전조치를 보완하세요.');\n      }\n      safety.verified = true;\n      return result('progress', '실습의 차단 확인을 완료했습니다. 모든 필수 조치가 완료됐는지 확인하세요.');\n  }\n}\n\nexport function judgeEntry(run) {\n  if (run.completed) return result('blocked', '이번 작업은 완료했습니다. 다시 연습하면 새 작업을 시작합니다.');\n  run.attempts += 1;\n  const safety = run.safety;\n  if (!safety.isolated || !safety.locked || !safety.residualCleared) {\n    let reason = '잠금 뒤 차단 확인을 생략해 불완전한 차단을 발견하지 못했습니다. 작업 전에 차단의 유효성을 확인해야 합니다.';\n    if (!safety.isolated || !safety.lockPresent) {\n      reason = '벨트가 멈춰 있어도 다시 움직일 수 있습니다. 정지 표시는 에너지 차단과 잠금의 확인을 대신하지 못합니다.';\n    } else if (!safety.locked) {\n      reason = '자물쇠가 보이는 것만으로 안전해지지 않습니다. 해당 설비의 에너지를 차단하고 그 차단 상태를 유지하도록 잠가야 합니다.';\n    } else if (safety.verified === false) {\n      reason = '실습에서는 필요한 잔류 에너지 안전조치가 끝나지 않아 위험한 에너지가 남아 있습니다. 안전조치를 보완하고 차단을 확인하세요.';\n    }\n    return { kind: 'wrong', reason, effect: 'accident' };\n  }\n  if (!allSafe(safety)) return result('incomplete', '아직 필수 조치가 끝나지 않았습니다. 빠진 단계를 완료한 뒤 작업에 들어가세요.');\n  run.completed = true;\n  return result('success', '멈춰 있다는 표시를 믿고 들어가지 않았습니다. 직접 차단하고 본인 자물쇠·표지를 체결한 뒤, 차단을 확인하고 작업에 들어갔습니다.');\n}\n\nexport function rewind(run) {\n  run.rewinds += 1;\n  return run;\n}\n\nexport function serializeRun(run) {\n  const payload = {\n    observed: [...run.observed], attempts: run.attempts, rewinds: run.rewinds,\n    completed: run.completed, safety: { ...run.safety },\n  };\n  runFromPayload(payload);\n  return payload;\n}\n\nfunction exactObject(value, keys, name) {\n  if (!value || typeof value !== 'object' || Array.isArray(value)\n    || ![Object.prototype, null].includes(Object.getPrototypeOf(value))) {\n    throw new TypeError(`${name}는 객체여야 합니다.`);\n  }\n  const actual = Object.keys(value);\n  if (actual.length !== keys.length || actual.some((key) => !keys.includes(key))) {\n    throw new TypeError(`${name} 필드가 올바르지 않습니다.`);\n  }\n}\n\nexport function runFromPayload(payload) {\n  exactObject(payload, runKeys, 'run');\n  exactObject(payload.safety, safetyKeys, 'safety');\n  if (!Array.isArray(payload.observed) || payload.observed.length > targetIds.size\n    || payload.observed.some((id) => !targetIds.has(id))\n    || new Set(payload.observed).size !== payload.observed.length) {\n    throw new TypeError('조사 기록이 올바르지 않습니다.');\n  }\n  for (const key of ['attempts', 'rewinds']) {\n    if (!Number.isSafeInteger(payload[key]) || payload[key] < 0 || payload[key] > counterLimit) {\n      throw new TypeError('기록 횟수가 올바르지 않습니다.');\n    }\n  }\n  if (typeof payload.completed !== 'boolean' || safetyKeys.some((key) => typeof payload.safety[key] !== 'boolean')) {\n    throw new TypeError('안전조치 상태는 불리언이어야 합니다.');\n  }\n  const safety = payload.safety;\n  if ((safety.lockPresent && !safety.isolated)\n    || (safety.locked && (!safety.isolated || !safety.lockPresent))\n    || (safety.tagged && !safety.locked)\n    || (safety.residualCleared && (!safety.isolated || !safety.locked))\n    || (safety.verified && (!safety.isolated || !safety.locked || !safety.residualCleared))\n    || (payload.completed && (!allSafe(safety) || payload.attempts < 1))) {\n    throw new TypeError('서로 모순되는 안전조치 상태입니다.');\n  }\n  return {\n    observed: new Set(payload.observed), attempts: payload.attempts, rewinds: payload.rewinds,\n    completed: payload.completed, safety: { ...safety },\n  };\n}\nimport assert from 'node:assert/strict';\nimport {\n  ACTIONS, SAFETY_STEPS, createRun, inspect, applyAction, judgeEntry,\n  rewind, serializeRun, runFromPayload,\n} from '../src/scenario.mjs';\n\nlet count = 0;\nfunction test(name, check) {\n  check();\n  count += 1;\n  console.log(`PASS ${name}`);\n}\nconst finishHazardSteps = (run) => ['isolate-energy', 'attach-personal-lock', 'clear-residual-energy']\n  .forEach((id) => assert.equal(applyAction(run, id).kind, 'progress'));\nconst finishSteps = (run) => {\n  finishHazardSteps(run);\n  applyAction(run, 'attach-tag');\n  applyAction(run, 'verify-isolation');\n};\n\ntest('새 한 판의 Set과 안전조치 객체가 서로 독립적이다', () => {\n  const first = createRun();\n  const second = createRun();\n  assert.notEqual(first.observed, second.observed);\n  assert.notEqual(first.safety, second.safety);\n  inspect(first, 'work-access');\n  applyAction(first, 'isolate-energy');\n  assert.equal(second.observed.size, 0);\n  assert.ok(Object.values(second.safety).every((value) => value === false));\n  assert.deepEqual([second.attempts, second.rewinds, second.completed], [0, 0, false]);\n});\ntest('설명 조사는 안전조치 또는 판단을 대신하지 않는다', () => {\n  const run = createRun();\n  const before = { ...run.safety };\n  inspect(run, 'work-access');\n  inspect(run, 'energy-isolator');\n  inspect(run, 'energy-isolator');\n  assert.equal(run.observed.size, 2);\n  assert.deepEqual(run.safety, before);\n  assert.equal(run.attempts, 0);\n  assert.equal(applyAction(run, 'enter-work').effect, 'accident');\n});\ntest('미조치 진입은 실제 위험 상태에 의한 사고이며 1회 판단이다', () => {\n  const run = createRun();\n  const verdict = applyAction(run, 'enter-work');\n  assert.equal(verdict.kind, 'wrong');\n  assert.equal(verdict.effect, 'accident');\n  assert.equal(run.attempts, 1);\n  assert.equal(run.completed, false);\n});\ntest('모든 필수 안전조치 후 진입은 성공한다', () => {\n  const run = createRun();\n  finishSteps(run);\n  assert.ok(SAFETY_STEPS.every(({ key }) => run.safety[key]));\n  assert.equal(run.attempts, 0);\n  assert.equal(applyAction(run, 'enter-work').kind, 'success');\n  assert.equal(run.completed, true);\n  assert.equal(run.attempts, 1);\n});\ntest('위험 에너지가 해소됐을 때 표지 또는 확인 누락은 사고가 아닌 미완료다', () => {\n  for (const missing of ['tagged', 'verified', 'both']) {\n    const run = createRun();\n    finishHazardSteps(run);\n    if (missing === 'tagged') applyAction(run, 'verify-isolation');\n    if (missing === 'verified') applyAction(run, 'attach-tag');\n    const verdict = applyAction(run, 'enter-work');\n    assert.equal(verdict.kind, 'incomplete');\n    assert.equal(verdict.effect, undefined);\n    assert.equal(run.completed, false);\n  }\n});\ntest('눈에 보이는 잘못된 자물쇠는 올바른 잠금으로 인정하지 않는다', () => {\n  const run = createRun();\n  applyAction(run, 'isolate-energy');\n  applyAction(run, 'attach-wrong-lock');\n  assert.equal(run.safety.lockPresent, true);\n  assert.equal(run.safety.locked, false);\n  assert.equal(applyAction(run, 'enter-work').effect, 'accident');\n  applyAction(run, 'attach-personal-lock');\n  applyAction(run, 'attach-tag');\n  applyAction(run, 'clear-residual-energy');\n  applyAction(run, 'verify-isolation');\n  assert.equal(applyAction(run, 'enter-work').kind, 'success');\n});\ntest('잘못된 잠금으로 바꾸면 기존 종속 안전조치는 무효화된다', () => {\n  const run = createRun();\n  finishSteps(run);\n  applyAction(run, 'attach-wrong-lock');\n  assert.deepEqual(run.safety, {\n    isolated: true, lockPresent: true, locked: false, tagged: false, residualCleared: false, verified: false,\n  });\n  assert.deepEqual(runFromPayload(serializeRun(run)).safety, run.safety);\n});\ntest('잔류 에너지 미조치는 위험 상태이며 확인 행동은 차단된다', () => {\n  const run = createRun();\n  applyAction(run, 'isolate-energy');\n  applyAction(run, 'attach-personal-lock');\n  applyAction(run, 'attach-tag');\n  const before = serializeRun(run);\n  assert.equal(applyAction(run, 'verify-isolation').kind, 'blocked');\n  assert.deepEqual(serializeRun(run), before);\n  assert.equal(applyAction(run, 'enter-work').effect, 'accident');\n});\ntest('선행 조치 없이 수행하는 조작은 상태를 바꾸지 않는다', () => {\n  for (const actionId of ['attach-personal-lock', 'attach-wrong-lock', 'attach-tag', 'clear-residual-energy', 'verify-isolation']) {\n    const run = createRun();\n    const before = serializeRun(run);\n    assert.equal(applyAction(run, actionId).kind, 'blocked');\n    assert.deepEqual(serializeRun(run), before);\n  }\n});\ntest('잘못된 대상과 행동 ID는 어떤 변경보다 먼저 거부된다', () => {\n  const run = createRun();\n  finishSteps(run);\n  applyAction(run, 'enter-work');\n  const before = serializeRun(run);\n  for (const id of ['worker', 'lock', 'control', 'unknown', null, {}]) assert.throws(() => inspect(run, id), RangeError);\n  for (const id of ['remove', 'notify', 'hold', 'start', null, {}]) assert.throws(() => applyAction(run, id), RangeError);\n  assert.deepEqual(serializeRun(run), before);\n});\ntest('반복 조작은 판단 횟수를 증가시키지 않으며 상태가 동일하다', () => {\n  const run = createRun();\n  finishSteps(run);\n  const before = serializeRun(run);\n  for (const { id } of ACTIONS.filter(({ id }) => id !== 'enter-work' && id !== 'attach-wrong-lock')) {\n    applyAction(run, id);\n  }\n  assert.deepEqual(serializeRun(run), before);\n});\ntest('되감기는 관찰·판단·안전조치를 유지하고 횟수만 증가한다', () => {\n  const run = createRun();\n  inspect(run, 'work-access');\n  applyAction(run, 'isolate-energy');\n  applyAction(run, 'attach-wrong-lock');\n  applyAction(run, 'enter-work');\n  const before = serializeRun(run);\n  rewind(run);\n  assert.deepEqual(serializeRun(run), { ...before, rewinds: 1 });\n  assert.equal(run.safety.locked, false);\n});\ntest('완료한 한 판은 추가 조작과 재판정을 차단한다', () => {\n  const run = createRun();\n  finishSteps(run);\n  applyAction(run, 'enter-work');\n  const before = serializeRun(run);\n  for (const { id } of ACTIONS) assert.equal(applyAction(run, id).kind, 'blocked');\n  assert.equal(judgeEntry(run).kind, 'blocked');\n  assert.deepEqual(serializeRun(run), before);\n});\ntest('JSON 왕복은 독립된 Set과 안전조치 사본을 만든다', () => {\n  const run = createRun();\n  inspect(run, 'energy-isolator');\n  finishSteps(run);\n  applyAction(run, 'enter-work');\n  const restored = runFromPayload(JSON.parse(JSON.stringify(serializeRun(run))));\n  assert.deepEqual(serializeRun(restored), serializeRun(run));\n  assert.notEqual(restored.observed, run.observed);\n  assert.notEqual(restored.safety, run.safety);\n  restored.completed = false;\n  assert.equal(judgeEntry(restored).kind, 'success');\n  assert.equal(run.attempts, 1);\n});\ntest('전송 객체의 알 수 없는 필드·ID·타입·횟수를 거부한다', () => {\n  const valid = serializeRun(createRun());\n  const malformed = [\n    null, [], {}, { ...valid, extra: true }, { ...valid, safety: { ...valid.safety, extra: false } },\n    { ...valid, safety: {} }, { ...valid, observed: new Set() }, { ...valid, observed: ['worker'] },\n    { ...valid, observed: ['work-access', 'work-access'] }, { ...valid, attempts: -1 },\n    { ...valid, attempts: 0.5 }, { ...valid, attempts: '1' }, { ...valid, attempts: 1_000_001 },\n    { ...valid, rewinds: NaN }, { ...valid, rewinds: Infinity }, { ...valid, completed: 1 },\n    { ...valid, safety: { ...valid.safety, isolated: 1 } },\n  ];\n  for (const payload of malformed) assert.throws(() => runFromPayload(payload), TypeError);\n});\ntest('불가능한 안전조치 종속 관계와 허위 완료 상태를 거부한다', () => {\n  const valid = serializeRun(createRun());\n  for (const key of ['lockPresent', 'locked', 'tagged', 'residualCleared', 'verified']) {\n    assert.throws(() => runFromPayload({ ...valid, safety: { ...valid.safety, [key]: true } }), TypeError);\n  }\n  assert.throws(() => runFromPayload({ ...valid, completed: true }), TypeError);\n  const ready = createRun();\n  finishSteps(ready);\n  assert.throws(() => runFromPayload({ ...serializeRun(ready), completed: true }), TypeError);\n});\nconsole.log(`${count} scenario tests passed.`);\n# SAFEPLAY 작업자 시점 플레이 초안\n\n이 폴더는 `docs/시나리오.md` v3를 체험하는 독립 초안이다. 사용자는 레미콘 컨베이어 점검구의 이물질을 제거할 작업자이며, 전체 공장뷰에서 B/C를 선택하고 안전한 점검구 밖에서 시작한다. 이동 → 차단 지점 상호작용 → 안전조치 → 점검구 진입 → 사고·되감기 또는 성공을 한 판으로 연결한다.\n\n기술은 저장소의 Phaser 4.2.1, HTML/CSS, JavaScript ES 모듈 및 Node 기본 모듈이다. 공장뷰는 기존 전경을 읽는다. 현장 배경과 작업자 시트는 기존 참고 이미지를 바탕으로 새로 생성한 자료이며 복사본이 아니다. 실제 산출물은 2172×724 배경과 1254×1254 작업자 시트이고 `assets/assets.json`의 측정값으로 배치한다. 생성 프롬프트는 `assets/generation-prompts.md`에 기록했다. 기존 루트 구현·문서·vendor·reference는 수정하지 않는다. `reference/`에서 런타임 import하지 않는다.\n\n## 독립 함수 계약\n\n작업 시작 시 참조한 `docs/contract.md`는 운전원 판정용 계약이었다. 이후 원격 `main`의 `af2f465`가 `docs/contract.md`와 `docs/결정사항.md`를 삭제했고, 이 통합에서 해당 원격 변경을 보존했다. 아래는 그 삭제와 별개로 이 초안의 독립 계약이다. `control`, `lock`, `worker`, `remove`, `notify`, `hold`, `start`를 새 뜻으로 재사용하지 않으며, 루트 `AGENTS.md`의 운전원용 지침은 이번 초안 작업에서 수정하지 않았다. 실제 루트 구현에 통합하려면 담당자 합의 뒤 제공 함수·호출부·검사를 함께 변경한다.\n\n`src/scenario.mjs`는 DOM·Phaser·통신 없이 다음을 제공한다.\n\n- `SAFETY_STEPS`: `{key,label}` 5개. `isolated`, `locked`, `tagged`, `residualCleared`, `verified`가 필수다.\n- `TARGETS`: `{id,title,text,fact}`. `work-access`와 `energy-isolator`. 본문은 v3 문구를 그대로 사용한다.\n- `ACTIONS`: `{id,label,targetId}`. 차단 지점의 `isolate-energy`, `attach-personal-lock`, `attach-wrong-lock`, `attach-tag`, `clear-residual-energy`, `verify-isolation`; 점검구의 `enter-work`.\n- `createRun()`: `{observed:Set, attempts:0, rewinds:0, completed:false, safety:{isolated:false,lockPresent:false,locked:false,tagged:false,residualCleared:false,verified:false}}`.\n- `inspect(run,targetId)`: 유효한 대상만 관찰 Set에 추가하고 대상을 반환한다. 안전조치와 판단 횟수는 바꾸지 않는다.\n- `applyAction(run,actionId)`: `{kind,reason,effect?}`를 반환한다. 종류는 `progress`, `blocked`, `wrong`, `incomplete`, `success`다. 모르는 ID는 어떤 변경보다 먼저 예외 처리한다. 완료한 한 판은 추가 조작을 차단한다.\n- `judgeEntry(run)`: 작업 진입 판단마다 `attempts`를 1회 올린다. 차단·올바른 잠금·잔류 에너지 조치 중 하나라도 없으면 `wrong` + `effect:'accident'`; 이 셋은 끝났으나 표지·확인이 누락되면 `incomplete`; 모든 필수 조치가 끝났으면 `success`와 `completed=true`다. 완료한 판의 재판정은 `blocked`이며 횟수를 늘리지 않는다. 앱은 `enter-work`를 `applyAction`으로 한 번만 호출한다.\n- `rewind(run)`: `rewinds`만 증가한다. 안전조치·관찰·판단·완료 상태를 유지한다. 앱은 사고 뒤 카드에서만 호출하며 플레이어를 진입 전 안전한 위치로 돌린다.\n- `serializeRun(run)`: Set을 배열로 바꾸고 검증한 JSON 전송 객체를 반환한다.\n- `runFromPayload(payload)`: 정확한 필드·허용 ID·불리언·중복 없는 관찰 배열·0~1,000,000의 정수 횟수를 검증하고 독립된 Set·안전조치 객체로 복원한다. 알 수 없는 필드와 불가능한 종속 상태를 거부한다.\n\n안전조치 선행 조건: 차단 → 본인 잠금; 올바른 잠금 → 표지; 차단+올바른 잠금 → 잔류 에너지 조치; 차단+올바른 잠금+잔류 에너지 조치 → 확인. `lockPresent`는 자물쇠가 보인다는 상태로 `locked`와 다르다. 잘못된 잠금으로 변경하면 `locked`, `tagged`, `residualCleared`, `verified`를 false로 되돌린다. 올바른 잠금을 다시 수행해 보완할 수 있다. 같은 유효 조작의 반복은 안전조치와 횟수에 추가 변화를 만들지 않는다.\n\n서버는 자체 모듈로 `runFromPayload` 검증 후 재판정한다. 성공 전송에는 `completed=true`가 포함되므로 검증한 사본의 `completed=false`를 명시적으로 설정하고 `judgeEntry`를 한 번 호출한다. 클라이언트 결과 문자열을 판정 근거로 신뢰하지 않는다. 이 상태 재판정은 행동 이력을 인증하는 기능이 아니며 성적 저장·인증은 범위 밖이다. 서버가 증가시킨 판단 횟수는 클라이언트의 기록으로 되돌려 붙이지 않는다. AI는 재판정 결과에 보충 설명 3문장만 제공한다.\n\n## 시뮬레이션 가정과 현장 확인\n\n이 초안은 아직 승인된 실제 설비 작업 절차가 아니다. `residualCleared=false`는 위험한 잔류 에너지가 남아 있는 실습 상태로 명시한다. 잘못된 체결은 차단 장치를 유지하지 못하는 다른 위치에 자물쇠를 단 실습 상태다. 표지·확인 누락만으로 무작위 사고를 만들지 않는다. 조치 버튼은 특정 장치를 조작하는 실제 순서·기동 시도 방법을 가르치지 않고 상태 변화를 체험하게 한다.\n\n해당 컨베이어의 에너지 종류와 차단 지점, 본인 자물쇠 체결 위치, 잔류 에너지 처리 방법, 차단 확인 방법, 작업자의 권한, 체결 실패 원인과 장면 배치는 사내 설비 절차·교육자료 및 담당자 대조 후 확정해야 한다. 시작 안내에 초안과 현장 절차 확인 필요를 짧게 표시한다.\n\n## 구현 및 확인 목록\n\n- 아트 구현: 원본 공장 전경 유지, 새 현장·작업자 이미지 및 측정 메타데이터 제공. 작업자 발 접촉점과 프레임 경계를 반영했다. 생성 이미지의 가장자리 품질과 프레임별 인물 높이 차이는 남은 시각적 한계다.\n- 현장 확인: 가까운 대상에서 E 조사, 좌우 키 이동, x=76/3124 경계, 카메라 이동·경계, 시작 위치 x=704를 Chrome에서 확인했다. 연속 키 누르기와 창 비활성화의 실제 동작은 수동 확인하지 않았다.\n- 앱·패널 확인: 미조치 진입 → 사고 카드 → Escape 닫기 차단 → 되감기, 잘못된 잠금 → 올바른 잠금 보완, 표지·확인 누락의 미완료, 다섯 조치 완료 후 성공을 Chrome에서 확인했다.\n- 접근성·재진입 확인: 방향키·Space·E·Escape와 클릭 조작, 움직임 줄이기에서 사고 카드·되감기 도달을 확인했다. 재연습 뒤 캔버스 한 개와 초기 위치·상태를 확인했다. 연속 입력·blur 처리와 타이머 정리는 소스 검토 범위다.\n- 서버 확인: Node 검사에서 정적 허용 목록·비공개 경로 차단·재판정·입력 제한·제공자 모의 응답·취소를 확인했다. `?ai=on`의 실제 키 미설정 요청은 고정 설명 3문장으로 복귀했다. 유료 OpenAI 호출은 수행하지 않았다.\n- 기록 확인: 공장 왕복에서 잠금 상태·위치·횟수 유지; 다시 연습에서 다섯 조치·횟수 0·위치 x=704로 초기화했다.\n- QA 결과: 시나리오 16개와 서버 17개, 합계 33개 Node 검사 통과. 앱·공장뷰·현장·시나리오·피드백·서버 구문 검사 통과. Chrome 1280×720에서 현장 배치와 결과 화면의 가로 넘침 없음을 확인했고 콘솔 오류·경고도 없었다. 상세 경로와 스크린샷은 `qa/REPORT.md`에 기록했다. 모바일은 아직 확인하지 않았다.\n",
